import{_ as p,r as n,o,c,e as a,a as l,s as i}from"./chunks/framework.CXcwiNg-.js";const b=JSON.parse('{"title":"权限 - October CMS - 3.x","titleTemplate":false,"description":"了解如何在后端面板中控制权限。","frontmatter":{"subtitle":"了解如何在后端面板中控制权限。"},"headers":[{"level":2,"title":"权限代码","slug":"权限代码","link":"#权限代码","children":[{"level":3,"title":"嵌套权限","slug":"嵌套权限","link":"#嵌套权限","children":[]}]},{"level":2,"title":"访问级别","slug":"访问级别","link":"#访问级别","children":[{"level":3,"title":"超级用户","slug":"超级用户","link":"#超级用户","children":[]},{"level":3,"title":"角色","slug":"角色","link":"#角色","children":[]},{"level":3,"title":"角色层级","slug":"角色层级","link":"#角色层级","children":[]}]},{"level":2,"title":"注册权限","slug":"注册权限","link":"#注册权限","children":[]},{"level":2,"title":"限制对后端页面的访问","slug":"限制对后端页面的访问","link":"#限制对后端页面的访问","children":[]},{"level":2,"title":"限制对功能的访问","slug":"限制对功能的访问","link":"#限制对功能的访问","children":[]}],"relativePath":"3.x/zh-cn/extend/backend/permissions.md","filePath":"3.x/zh-cn/extend/backend/permissions.md"}'),r={name:"3.x/zh-cn/extend/backend/permissions.md"};function u(k,s,d,g,h,m){const t=n("pre-heading"),e=n("post-heading");return o(),c("div",null,[a(t),s[0]||(s[0]=l("h1",null,"权限",-1)),a(e),s[1]||(s[1]=i(`<p>权限允许用户在后端面板中拥有特定的权限和功能。例如，创建或删除记录，或查看服务器日志。这些权限基于分配的角色，并且可以按用户单独授予。</p><h2 id="权限代码"><a href="#权限代码" class="header-anchor">#</a> 权限代码</h2><p>权限代码定义单个权限，是使用&quot;点&quot;表示法的字符串键，例如 <code>some.area.permission_name</code>。这些权限通过直接分配或通过角色继承的方式授予用户。</p><p>当检查用户是否拥有特定权限时，该用户角色的权限会被继承，然后被直接应用于该用户的任何权限覆盖。例如：</p><ul><li>如果用户 <strong>Bob</strong> 拥有一个名为 <strong>Genius</strong> 的角色；并且</li><li>角色 <strong>Genius</strong> 拥有 <code>eat_cake</code> 权限；但是</li><li><strong>Bob</strong> 的 <code>eat_cake</code> 权限被明确设置为拒绝；那么</li><li><strong>Bob</strong> 将无法 <code>eat_cake</code>。</li></ul><p>但是：</p><ul><li>如果 <strong>Bob</strong> 被直接分配了 <code>eat_vegetables</code> 权限，但是；</li><li><strong>Genius</strong> 角色没有该权限，那么；</li><li><strong>Bob</strong> 仍然可以 <code>eat_vegetables</code>。</li></ul><h3 id="嵌套权限"><a href="#嵌套权限" class="header-anchor">#</a> 嵌套权限</h3><p>权限代码支持嵌套结构，以便在选择权限时提供更清晰的界面。要嵌套权限代码，&quot;点&quot;值必须是其父级的直接后代，并且支持无限层级嵌套。</p><p>在以下示例中，必须先授予 <code>manage_entries</code> 权限，<code>manage_entries.create</code> 和 <code>manage_entries.publish</code> 代码才可用。其可视化表示如下：</p><pre class="dir-container"><code><p>├── manage_entries
|   ├── manage_entries.create
|   └── manage_entries.publish
└── delete_entries</p>
</code></pre><h2 id="访问级别"><a href="#访问级别" class="header-anchor">#</a> 访问级别</h2><p>对 October CMS 实例所有部分的访问由权限系统控制。<code>BackendAuth::userHasAccess</code> 方法是检查当前用户是否已登录并拥有特定区域权限的快捷方式。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token comment">// Returns true if the user has permission</span>
<span class="token variable">$permissionGranted</span> <span class="token operator">=</span> <span class="token class-name static-context">BackendAuth</span><span class="token operator">::</span><span class="token function">userHasAccess</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;utilities.logs&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h3 id="超级用户"><a href="#超级用户" class="header-anchor">#</a> 超级用户</h3><p>管理员可以被授予一个名为&quot;超级用户&quot;的特殊标志，允许访问所有区域。授予后，权限系统将被绕过，可访问所有区域。超级用户对其他普通管理员不可见。</p><div class="custom-block warning"><p>任何超级用户都可以创建和删除其他超级用户，因此该权限只应授予最高级别的管理员或应用程序所有者。</p></div><h3 id="角色"><a href="#角色" class="header-anchor">#</a> 角色</h3><p>角色使用 <code>Backend\\Models\\UserRole</code> 模型，是具有名称和描述的权限分组，用于标识角色。管理员一次只能被分配一个角色。</p><p>October CMS 默认提供两个系统角色，分别为 <code>developer</code> 和 <code>publisher</code>。可以创建任意数量的自定义角色，设置各自的权限组合并应用于用户。</p><div class="custom-block tip"><p>系统角色的权限无法更改，但如果不需要可以将其删除。</p></div><h3 id="角色层级"><a href="#角色层级" class="header-anchor">#</a> 角色层级</h3><p>每个角色在后端面板中都被分配了一个排名位置，在数据库中表示为 <code>sort_order</code> 列。这允许建立基本的组织结构，使用户只能管理低于其自身角色的角色。</p><p>在以下示例中，<strong>高级编辑</strong> 可以管理所有用户，其级别高于 <strong>编辑</strong> 和 <strong>事实核查员</strong> 角色。而 <strong>事实核查员</strong> 角色无法查看或管理其上级的用户和权限，即 <strong>编辑</strong> 和 <strong>高级编辑</strong> 角色。</p><ul><li>Senior Editor</li><li>Staff Writer</li><li>Fact Checker</li></ul><p>如果授予了 <strong>管理管理员 → 管理角色</strong> 权限，用户可以管理其当前角色以下的用户、权限和角色。</p><h2 id="注册权限"><a href="#注册权限" class="header-anchor">#</a> 注册权限</h2><p>插件可以通过在<a href="./../extending.html">插件注册文件</a>中重写 <code>registerPermissions</code> 方法来注册后端用户权限。权限被定义为一个数组，其键对应权限键，值对应权限描述。权限键由作者名称、插件名称和功能名称组成。以下是示例代码。</p><div class="language- extra-class"><pre class="language-text"><code>acme.blog.access_categories
</code></pre></div><p>下一个示例展示了如何注册后端权限项。权限通过权限键和描述来定义。在后端权限管理用户界面中，权限显示为复选框列表。后端控制器可以使用插件定义的权限来限制用户对页面或功能的访问。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">registerPermissions</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token keyword">return</span> <span class="token punctuation">[</span>
        <span class="token string single-quoted-string">&#39;acme.blog.access_posts&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span>
            <span class="token string single-quoted-string">&#39;label&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;Manage the blog posts&#39;</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;tab&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;Blog&#39;</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;order&#39;</span> <span class="token operator">=&gt;</span> <span class="token number">200</span><span class="token punctuation">,</span>
        <span class="token punctuation">]</span><span class="token punctuation">,</span>
        <span class="token comment">// ...</span>
    <span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>您还可以指定一个 <code>roles</code> 选项作为数组，其中每个值为角色 API 代码。当使用此代码创建角色时，它将成为一个系统角色，始终将此权限授予拥有该角色的用户。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">registerPermissions</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token keyword">return</span> <span class="token punctuation">[</span>
        <span class="token string single-quoted-string">&#39;acme.blog.access_categories&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span>
            <span class="token string single-quoted-string">&#39;label&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;Manage the blog categories&#39;</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;tab&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;Blog&#39;</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;order&#39;</span> <span class="token operator">=&gt;</span> <span class="token number">200</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;roles&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;developer&#39;</span><span class="token punctuation">]</span>
        <span class="token punctuation">]</span>
        <span class="token comment">// ...</span>
    <span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><h2 id="限制对后端页面的访问"><a href="#限制对后端页面的访问" class="header-anchor">#</a> 限制对后端页面的访问</h2><p>在后端控制器类中，您可以指定访问控制器提供的页面所需的权限。这通过控制器的 <code>$requiredPermissions</code> 属性完成。此属性应包含一个权限键数组。如果用户权限与列表中的任何权限匹配，框架将允许用户查看控制器页面。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">namespace</span> <span class="token package">Acme<span class="token punctuation">\\</span>Blog<span class="token punctuation">\\</span>Controllers</span><span class="token punctuation">;</span>

<span class="token keyword">use</span> <span class="token package">Backend<span class="token punctuation">\\</span>Classes<span class="token punctuation">\\</span>BackendController</span><span class="token punctuation">;</span>

<span class="token keyword">class</span> <span class="token class-name-definition class-name">Posts</span> <span class="token keyword">extends</span> <span class="token class-name">BackendController</span>
<span class="token punctuation">{</span>
    <span class="token keyword">public</span> <span class="token variable">$requiredPermissions</span> <span class="token operator">=</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;acme.blog.access_posts&#39;</span><span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>您还可以使用<strong>星号</strong>符号来表示&quot;所有权限&quot;条件。在下一个示例中，控制器页面对所有拥有以 &quot;acme.blog.&quot; 字符串开头的权限的用户可访问：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token variable">$requiredPermissions</span> <span class="token operator">=</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;acme.blog.*&#39;</span><span class="token punctuation">]</span><span class="token punctuation">;</span>
</code></pre></div><h2 id="限制对功能的访问"><a href="#限制对功能的访问" class="header-anchor">#</a> 限制对功能的访问</h2><p>后端用户模型具有允许确定用户是否拥有特定权限的方法。您可以使用此功能来限制后端用户界面的功能。后端用户支持的权限方法有 <code>userHasAccess</code> 和 <code>userHasPermission</code>。两个方法都接受两个参数：权限键字符串（或键字符串数组）和一个可选参数，指示第一个参数列出的所有权限都是必需的。</p><p><code>userHasAccess</code> 方法在用户是超级用户时对任何权限返回 <strong>true</strong>。<code>userHasPermission</code> 方法更严格，仅当用户在其账户中或通过其角色实际拥有指定权限时才返回 true。通常，<code>userHasAccess</code> 是首选方法，因为它尊重超级用户的绝对权力。以下示例展示了如何在控制器代码中使用这些方法。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token class-name static-context">BackendAuth</span><span class="token operator">::</span><span class="token function">userHasAccess</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;acme.blog.*&#39;</span><span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token comment">// ...</span>
<span class="token punctuation">}</span>

<span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token class-name static-context">BackendAuth</span><span class="token operator">::</span><span class="token function">userHasPermission</span><span class="token punctuation">(</span><span class="token punctuation">[</span>
    <span class="token string single-quoted-string">&#39;acme.blog.access_posts&#39;</span><span class="token punctuation">,</span>
    <span class="token string single-quoted-string">&#39;acme.blog.access_categories&#39;</span>
<span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token comment">// ...</span>
<span class="token punctuation">}</span>
</code></pre></div><p>您还可以在后端视图中使用这些方法来隐藏用户界面元素。下一个示例演示了如何在<a href="./../forms/form-controller.html">后端表单</a>中隐藏按钮。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token php language-php"><span class="token delimiter important">&lt;?php</span> <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token class-name static-context">BackendAuth</span><span class="token operator">::</span><span class="token function">userHasAccess</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;acme.blog.delete_categories&#39;</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">:</span> <span class="token delimiter important">?&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>button</span>
        <span class="token attr-name">type</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>button<span class="token punctuation">&quot;</span></span>
        <span class="token attr-name">class</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>oc-icon-trash-o btn-icon danger<span class="token punctuation">&quot;</span></span>
        <span class="token attr-name">data-request</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>onDelete<span class="token punctuation">&quot;</span></span>
        <span class="token attr-name">data-load-indicator</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>Deleting Category...<span class="token punctuation">&quot;</span></span>
        <span class="token attr-name">data-request-confirm</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>Do you really want to delete this category?<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>button</span><span class="token punctuation">&gt;</span></span>
<span class="token php language-php"><span class="token delimiter important">&lt;?php</span> <span class="token keyword">endif</span> <span class="token delimiter important">?&gt;</span></span>
</code></pre></div>`,44))])}const _=p(r,[["render",u]]);export{b as __pageData,_ as default};
